cardCss:
.dc-act { width:60px;height:60px;border-radius:9999px;display:inline-flex;align-items:center;justify-content:center;background:var(--action-btn-bg,#eef2f7);color:var(--ink-3,#64748b);border:none;cursor:pointer;transition:all .18s ease;font-size:25px; }
.dc-act:hover { background:var(--primary,#0f766e);color:#fff;transform:translateY(-2px);box-shadow:0 4px 12px rgba(15,118,110,.25); }
.dc-act:active { transform:scale(.9); }
.dc-act.is-active { background:var(--primary,#0f766e);color:#fff; }
.dc-act.act-mark.is-active { background:var(--unknown,#f43f5e);color:#fff; }
.dc-act.act-fav.is-active { background:var(--amber,#d97706);color:#fff; }
.dc-scroll { scrollbar-width:thin;scrollbar-color:var(--line) transparent; }
.dc-scroll::-webkit-scrollbar { width:8px; }
.dc-scroll::-webkit-scrollbar-thumb { background:var(--line);border-radius:8px; }
body.dark-mode .dc-act { background:#1f2937;color:#cbd5e1; }
body.dark-mode .dc-act:hover,body.dark-mode .dc-act.is-active { color:#fff; }

.ew-word { color: var(--primary, #0f766e); }
.ew-phon { color: var(--ink-2, #475569); }
.ew-index { color: var(--ink-3, #64748b); }
.ew-def-en { background: var(--action-btn-bg, #f1f5f9); border-left: 3px solid var(--primary, #0f766e); }
.dc-card.ew { border-left: 4px solid var(--primary, #0f766e); }
.dc-card.ew.highlighted { border-left-color: var(--unknown, #f43f5e); background: #fef6f3; }
body.dark-mode .ew-def-en { background: #1f2937; }
body.dark-mode .dc-card.ew.highlighted { background: #2a1417; }

cardJs:
(function () {
    'use strict';
    function esc(s) {
        if (s == null) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    function parseList(t) {
        if (t == null) return [];
        if (Array.isArray(t)) return t;
        if (typeof t !== 'string') return [String(t)];
        try {
            var arr = JSON.parse(t);
            if (Array.isArray(arr)) return arr;
        } catch (e) {}
        return [t];
    }
    // Renders the definition text only (no section label).
    function defBlock(items, hideableKey, hidden, extraClass) {
        if (hidden.has && hidden.has(hideableKey)) return '';
        if (!items.length) return '';
        var html = '';
        if (extraClass) {
            html += '<div class="' + extraClass + ' rounded-md p-2 pl-3 space-y-1" style="font-size:calc(16px*var(--card-font-scale,1));line-height:1.8">';
        } else {
            html += '<div class="space-y-1" style="font-size:calc(16px*var(--card-font-scale,1));line-height:1.8">';
        }
        items.forEach(function (t) { html += '<div>' + esc(t) + '</div>'; });
        html += '</div>';
        return html;
    }
    window.cardTemplate = {
        name: 'English Word (Simple)',
        fields: [
            { key: 'word', label: '单词', hideable: false },
            { key: 'phonetic_us', label: '音标' },
            { key: 'paraphrase_en', label: '英文释义' },
            { key: 'paraphrase_zh', label: '中文释义' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(k) { return hidden.has && hidden.has(k); }
            function h(k, html) { return isHidden(k) ? '' : html; }

            var markActive = data.is_unknown === 1 ? ' is-active' : '';
            var favActive = data.is_favorite === 1 ? ' is-active' : '';

            var html = '';
            // CRITICAL: root MUST carry data-card-id or init() never binds and all buttons die.
            html += '<div class="dc-card ew flex flex-col max-h-[560px] bg-[var(--card-bg)] text-[var(--ink)] border border-[var(--line)] rounded-2xl p-4 shadow-sm mb-4'
                + (data.is_unknown === 1 ? ' highlighted' : '') + '" data-card-id="' + data.id + '">';

            // Header: identity left, 3 actions right (no eye, no examples)
            html += '<div class="flex items-start justify-between gap-3 mb-3 shrink-0">';
            html += '<div class="flex items-baseline gap-2 flex-wrap min-w-0">';
            html += '<span class="ew-index text-xs font-semibold">' + String(data.current_order).padStart(2, '0') + '</span>';
            html += h('word', '<span class="ew-word text-2xl font-bold" style="font-size:calc(24px*var(--card-font-scale,1))">' + esc(d.word) + '</span>');
            html += h('phonetic_us', '<span class="ew-phon text-sm" style="font-size:calc(13px*var(--card-font-scale,1))">/' + esc(d.phonetic_us) + '/</span>');
            html += '</div>';
            html += '<div class="flex items-center gap-2 shrink-0">';
            html += '<button class="dc-act act-play" data-action="play" data-tooltip="发音"><i class="fa-solid fa-volume-high"></i></button>';
            html += '<button class="dc-act act-mark' + markActive + '" data-action="mark" data-tooltip="标记"><i class="fa-solid fa-bookmark"></i></button>';
            html += '<button class="dc-act act-fav' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>';
            html += '</div></div>';

            // Body (scrolls; buttons stay fixed)
            html += '<div class="dc-scroll flex-1 min-h-0 overflow-y-auto space-y-3">';
            html += defBlock(parseList(d.paraphrase_zh), 'paraphrase_zh', hidden, '');
            html += defBlock(parseList(d.paraphrase_en), 'paraphrase_en', hidden, 'ew-def-en');
            html += '</div></div>';
            return html;
        },
        init: function (cardElement, cardData, api) {
            var pb = cardElement.querySelector('[data-action="play"]');
            if (pb) pb.addEventListener('click', function () {
                var d = (api.getCardData().data) || {};
                api.playAudio(d.word || '');
                api.track('audio_play');
            });
            var mb = cardElement.querySelector('[data-action="mark"]');
            if (mb) mb.addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var fb = cardElement.querySelector('[data-action="favorite"]');
            if (fb) fb.addEventListener('click', function () {
                api.toggleFavorite().then(function () { api.rerender(); });
                api.track('favorite_toggle');
            });
            cardElement.querySelectorAll('[data-action]').forEach(function (btn) {
                btn.addEventListener('mouseenter', function () {
                    var t = btn.dataset.tooltip; if (t && api.showTooltip) api.showTooltip(btn, t);
                });
                btn.addEventListener('mouseleave', function () { if (api.hideTooltip) api.hideTooltip(); });
            });
        }
    };
})();
